import { useEffect, useRef, useState } from 'react'
import {
  formatNumber,
  getAnimatedStartValue,
  type ParsedNumericValue,
} from '@/utils/animatedNumber'

interface UseCountUpOnVisibleOptions {
  duration?: number
  threshold?: number
}

const useCountUpOnVisible = (
  parsedValueMap: Record<string, ParsedNumericValue | null>,
  options: UseCountUpOnVisibleOptions = {},
) => {
  const { duration = 1400, threshold = 0.25 } = options
  const sectionRef = useRef<HTMLElement | null>(null)
  const rafRef = useRef<number | null>(null)
  const [animatedValues, setAnimatedValues] = useState<Record<string, string>>({})
  const [isVisible, setIsVisible] = useState(false)
  const [hasAnimated, setHasAnimated] = useState(false)

  useEffect(() => {
    const current = sectionRef.current
    if (!current || hasAnimated) return

    const observer = new IntersectionObserver(
      entries => {
        const [entry] = entries
        if (entry?.isIntersecting) {
          setIsVisible(true)
          observer.disconnect()
        }
      },
      { threshold },
    )

    observer.observe(current)

    return () => observer.disconnect()
  }, [hasAnimated, threshold])

  useEffect(() => {
    if (!isVisible || hasAnimated) return

    const startAt = performance.now()

    const renderValues = (progress: number) => {
      const next: Record<string, string> = {}

      Object.entries(parsedValueMap).forEach(([key, parsed]) => {
        if (!parsed) return

        const start = getAnimatedStartValue(parsed.target)
        const current = start + (parsed.target - start) * progress
        const value =
          progress >= 1
            ? parsed.target
            : parsed.decimals > 0
              ? Number(current.toFixed(parsed.decimals))
              : Math.floor(current)

        next[key] = `${parsed.prefix}${formatNumber(value, parsed.decimals, parsed.useGrouping)}${parsed.suffix}`
      })

      setAnimatedValues(next)
    }

    const animate = (now: number) => {
      const elapsed = now - startAt
      const rawProgress = Math.min(elapsed / duration, 1)
      const easedProgress = 1 - (1 - rawProgress) ** 3

      renderValues(easedProgress)

      if (rawProgress < 1) {
        rafRef.current = requestAnimationFrame(animate)
      } else {
        setHasAnimated(true)
      }
    }

    renderValues(0)
    rafRef.current = requestAnimationFrame(animate)

    return () => {
      if (rafRef.current) {
        cancelAnimationFrame(rafRef.current)
      }
    }
  }, [duration, hasAnimated, isVisible, parsedValueMap])

  return {
    sectionRef,
    animatedValues,
  }
}

export default useCountUpOnVisible

