import './index.less'
import { useMemo } from 'react'
import useCountUpOnVisible from '@/hooks/useCountUpOnVisible'
import { parseNumericValue, type ParsedNumericValue } from '@/utils/animatedNumber'
import icon04 from '@/assets/icons/04.svg'
import icon16 from '@/assets/icons/16.svg'
import icon22 from '@/assets/icons/22.svg'
import icon24 from '@/assets/icons/24.svg'

interface StatItem {
  value: string
  label: string
}

interface TextStatItem {
  value: string
  label: string
  desc: string
}

interface ImpactSectionProps {
  title: string
  description: string
  topStats: StatItem[][]
  images: string[]
  deviceStats: { index: string; value: string; label: string }[]
  textStats: TextStatItem[]
  trustedByTitle: string
  trustedByDesc: string
}

const ImpactSection = ({
  title,
  description,
  topStats,
  images,
  deviceStats,
  textStats,
  trustedByTitle,
  trustedByDesc,
}: ImpactSectionProps) => {
  const deviceIndexIconMap: Record<string, string> = {
    '04': icon04,
    '16': icon16,
    '22': icon22,
    '24': icon24,
  }

  const parsedValueMap = useMemo(() => {
    const map: Record<string, ParsedNumericValue | null> = {}

    topStats.forEach((group, gIdx) => {
      group.forEach((item, idx) => {
        map[`top-${gIdx}-${idx}`] = parseNumericValue(item.value)
      })
    })

    deviceStats.forEach((item, idx) => {
      map[`device-${idx}`] = parseNumericValue(item.value)
    })

    textStats.forEach((item, idx) => {
      map[`text-${idx}`] = parseNumericValue(item.value)
    })

    return map
  }, [topStats, deviceStats, textStats])

  const { sectionRef, animatedValues } = useCountUpOnVisible(parsedValueMap)

  const getAnimatedValue = (key: string, fallback: string) =>
    animatedValues[key] ?? fallback

  return (
    <section className="impact" ref={sectionRef}>
      <div className="impact__header">
        <h2 className="impact__title">{title}</h2>
        <p className="impact__desc">{description}</p>
      </div>

      <div className="impact__main">
        <div className="impact__stats-left">
          {topStats.map((group, gIdx) => (
            <div className="impact__stat-group" key={gIdx}>
              {group.map((item, idx) => (
                <div className="impact__stat-item" key={idx}>
                  <span className="impact__stat-value">
                    {getAnimatedValue(`top-${gIdx}-${idx}`, item.value)}
                  </span>
                  <span className="impact__stat-label">{item.label}</span>
                </div>
              ))}
            </div>
          ))}
        </div>
        <div className="impact__images">
          {images.map((src, idx) => (
            <div className="impact__image-cell" key={idx}>
              <img src={src} alt="" />
            </div>
          ))}
        </div>
      </div>

      <div className="impact__divider" />

      <div className="impact__device-stats">
        {deviceStats.map((item, idx) => (
          <div className="impact__device-card" key={idx}>
            <span className="impact__device-index">
              {deviceIndexIconMap[item.index] ? (
                <img src={deviceIndexIconMap[item.index]} alt="" aria-hidden="true" />
              ) : (
                item.index
              )}
            </span>
            <div className="impact__device-info">
              <span className="impact__device-value">
                {getAnimatedValue(`device-${idx}`, item.value)}
              </span>
              <span className="impact__device-label">{item.label}</span>
            </div>
          </div>
        ))}
      </div>

      <div className="impact__divider" />

      <div className="impact__footer">
        <div className="impact__text-stats">
          {textStats.map((item, idx) => (
            <div className="impact__text-item" key={idx}>
              <span className="impact__text-value">
                {getAnimatedValue(`text-${idx}`, item.value)}
              </span>
              <span className="impact__text-label">{item.label}</span>
              <span className="impact__text-desc">{item.desc}</span>
            </div>
          ))}
        </div>

        <div className="impact__trusted">
          <div className="impact__trusted-header">
            <span className="impact__trusted-title">{trustedByTitle}</span>
          </div>
          <p className="impact__trusted-desc">{trustedByDesc}</p>
        </div>
      </div>
    </section>
  )
}

export default ImpactSection
